:root {
  --navy: #0a0a23;
  --amber: #feac32;
  --link: #002ead;
  --bg: #f8f9fb;
  --text: #101425;
  --muted: #5b6175;
  --card: #ffffff;
  --border: #e7e9f0;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.5;
}
a { color: var(--link); text-decoration: none; }
a:hover { text-decoration: underline; }
.container { width: min(1180px, 92vw); margin: 0 auto; }
.site-header { background: var(--navy); color: #fff; position: sticky; top: 0; z-index: 20; }
.topbar { display: flex; align-items: center; gap: 16px; padding: 14px 0; }
.logo { color: #fff; font-weight: 800; letter-spacing: .2px; font-size: 1.15rem; }
.search-wrap { flex: 1; }
.search {
  width: 100%; border: 1px solid #3a3f63; border-radius: 10px;
  background: #131735; color: #fff; padding: 10px 12px;
}
.nav-links { display: flex; gap: 18px; }
.nav-links a { color: #f3f4ff; font-weight: 600; }
.menu-btn {
  display: none; border: 1px solid #4c527d; background: transparent; color: #fff;
  border-radius: 8px; padding: 8px 10px; cursor: pointer;
}
.mobile-nav {
  display: none; padding: 10px 0 14px; border-top: 1px solid #272c52;
}
.mobile-nav a { color: #f3f4ff; display: block; padding: 8px 0; font-weight: 600; }
.hero-banner {
  display: block; background: #11173a; color: #fff; text-align: center;
  padding: 10px 16px; border-top: 1px solid #2d3360; border-bottom: 1px solid #2d3360;
}
main { padding: 28px 0 56px; }
.section-title { font-size: 1.8rem; margin: 0 0 18px; letter-spacing: -.2px; }
.subtle { color: var(--muted); }
.featured {
  display: grid; grid-template-columns: 1.3fr 1fr; background: var(--card);
  border: 1px solid var(--border); border-radius: 16px; overflow: hidden; margin-bottom: 32px;
}
.thumb {
  min-height: 220px;
  background: linear-gradient(135deg, #1c2253, #27357a 55%, #3d56b7);
  position: relative;
}
.tag-pill {
  display: inline-block; padding: 4px 10px; border-radius: 999px;
  background: #eef2ff; color: #26327e; font-weight: 700; font-size: .78rem;
}
.tag-ai { background: #eee9ff; color: #4f2fad; }
.tag-scraping { background: #fff2dd; color: #985600; }
.tag-db { background: #e5f6f1; color: #05604a; }
.tag-es { background: #f3eaff; color: #603293; }
.tag-de { background: #e9f2ff; color: #244f8f; }
.featured-content { padding: 22px; }
.article-meta { display: flex; align-items: center; gap: 10px; color: var(--muted); font-size: .92rem; margin-top: 14px; }
.avatar {
  width: 30px; height: 30px; border-radius: 50%; background: linear-gradient(160deg,#c6d2ff,#7f95eb);
  border: 2px solid #fff; box-shadow: 0 0 0 1px #d8dded;
}
.grid {
  display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 18px;
}
.card {
  background: var(--card); border: 1px solid var(--border); border-radius: 14px; overflow: hidden;
}
.card .thumb { min-height: 145px; }
.card-body { padding: 14px; }
.card h3 { margin: 10px 0 0; font-size: 1.06rem; line-height: 1.35; }
.load-more {
  margin: 28px auto 0; display: inline-flex; border: 0; border-radius: 10px;
  background: var(--amber); color: #1b1202; font-weight: 800; padding: 12px 18px; cursor: pointer;
}
.center { text-align: center; }
.panel {
  background: #fff; border: 1px solid var(--border); border-radius: 16px; padding: 22px; margin-bottom: 24px;
}
.syllabus { display: grid; gap: 12px; }
.path {
  display: flex; align-items: center; gap: 12px; border: 1px solid var(--border);
  border-radius: 12px; padding: 12px 14px; background: #fff;
}
.icon { width: 34px; height: 34px; border-radius: 10px; background: #edf1ff; display: grid; place-items: center; color: #2a418f; font-weight: 800; }
.donation-hero { background: #fff7ea; border-color: #f0dfbf; }
.amount-tabs { display: flex; gap: 10px; margin: 16px 0 10px; flex-wrap: wrap; }
.amount-btn {
  border: 1px solid #dfc588; background: #fff; color: #5b3a00; border-radius: 10px;
  padding: 10px 14px; font-weight: 800; cursor: pointer;
}
.amount-btn.active { background: var(--amber); border-color: #e39a1f; color: #2b1b00; }
.donate-btn {
  margin-top: 12px; border: 0; border-radius: 10px; background: var(--navy); color: #fff;
  padding: 12px 18px; font-weight: 700; cursor: pointer;
}
.faq-item { border-top: 1px solid var(--border); }
.faq-q {
  width: 100%; border: 0; background: transparent; text-align: left; padding: 14px 2px;
  font-weight: 700; display: flex; justify-content: space-between; align-items: center; cursor: pointer;
}
.faq-a {
  max-height: 0; overflow: hidden; transition: max-height .25s ease; color: var(--muted);
}
.faq-a p { margin: 0 0 14px; }
.tag-header { margin-bottom: 16px; }
.tag-row { display: flex; gap: 10px; overflow-x: auto; padding-bottom: 8px; margin-bottom: 20px; }
.tag-chip {
  flex: 0 0 auto; background: #fff; border: 1px solid var(--border); border-radius: 999px;
  padding: 7px 12px; color: #2b324d; font-size: .88rem;
}
.site-footer { padding: 28px 0; color: var(--muted); font-size: .92rem; }
@media (max-width: 960px) {
  .grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .featured { grid-template-columns: 1fr; }
}
@media (max-width: 760px) {
  .search-wrap, .nav-links { display: none; }
  .menu-btn { display: inline-block; margin-left: auto; }
  .mobile-nav.open { display: block; }
  .grid { grid-template-columns: 1fr; }
}
EOF

cat > /app/output/script.js <<'EOF'
const articleData = [
  { tag: '#AI', cls: 'tag-ai', title: 'Shadow AI Explained: Why Employees Are Using AI Behind Your Back', author: 'Manish Shivanandhan', time: '15 hours ago', link: 'tag-ai.html' },
  { tag: '#web scraping', cls: 'tag-scraping', title: 'Traditional Scraping vs AI Scraping: A Practical Guide for Developers and Data Teams', author: 'Joel Olawanle', time: '16 hours ago', link: 'tag-web-scraping.html' },
  { tag: '#Databases', cls: 'tag-db', title: 'How Database Indexes Work – A Practical Guide with PostgreSQL Examples', author: 'iyiola', time: '20 hours ago', link: '#' },
  { tag: '#elasticsearch', cls: 'tag-es', title: 'How to Streamline Search in Web Applications with Elasticsearch', author: 'Oluwatobi', time: '21 hours ago', link: '#' },
  { tag: '#data-engineering', cls: 'tag-de', title: 'How to Build an Open Source Data Lake for Batch Ingestion', author: 'Puneet Singh', time: 'a day ago', link: '#' },
  { tag: '#AI', cls: 'tag-ai', title: 'The AI Governance Handbook: How to Build Responsible AI Systems That Actually Ship', author: 'Anita Verma', time: '2 days ago', link: 'tag-ai.html' },
  { tag: '#web scraping', cls: 'tag-scraping', title: 'How to Turn Websites into LLM-Ready Data Using Firecrawl', author: 'Sahil K', time: '3 days ago', link: 'tag-web-scraping.html' },
  { tag: '#web scraping', cls: 'tag-scraping', title: 'How to Use Python to Build Your Own Web Scraper', author: 'Abubakar', time: '4 days ago', link: 'tag-web-scraping.html' },
  { tag: '#AI', cls: 'tag-ai', title: 'GPT-5.4 vs GLM-5: Is Open Source Finally Matching Proprietary AI?', author: 'Lena Park', time: '5 days ago', link: 'tag-ai.html' }
];

function setupMenu() {
  const btn = document.querySelector('[data-menu-btn]');
  const menu = document.querySelector('[data-mobile-nav]');
  if (!btn || !menu) return;
  btn.addEventListener('click', () => menu.classList.toggle('open'));
}

function renderCard(item) {
  return `<article class="card"><div class="thumb"></div><div class="card-body"><a class="tag-pill ${item.cls}" href="${item.link}">${item.tag}</a><h3>${item.title}</h3><div class="article-meta"><div class="avatar"></div><span>${item.author}</span><span>· ${item.time}</span></div></div></article>`;
}

function setupLoadMore() {
  const grid = document.querySelector('[data-article-grid]');
  const btn = document.querySelector('[data-load-more]');
  if (!grid || !btn) return;
  let cursor = grid.children.length;
  btn.addEventListener('click', () => {
    const next = articleData.slice(cursor, cursor + 3);
    next.forEach(item => grid.insertAdjacentHTML('beforeend', renderCard(item)));
    cursor += next.length;
    if (cursor >= articleData.length) btn.disabled = true;
  });
}

function setupDonationTabs() {
  const tabs = document.querySelectorAll('[data-amount]');
  const text = document.querySelector('[data-donation-text]');
  if (!tabs.length || !text) return;
  tabs.forEach(tab => tab.addEventListener('click', () => {
    tabs.forEach(t => t.classList.remove('active'));
    tab.classList.add('active');
    const amount = tab.getAttribute('data-amount');
    const hoursMap = { '5': '250', '10': '500', '20': '1,000', '40': '2,000' };
    text.textContent = `Your $${amount} donation will provide ${hoursMap[amount]} hours of learning to people around the world each month.`;
    const sub = document.querySelector('[data-donation-sub]');
    if (sub) sub.textContent = `Donating $${amount} / month: edit amount · Secure donation`;
  }));
}

function setupFaq() {
  document.querySelectorAll('[data-faq-item]').forEach(item => {
    const q = item.querySelector('.faq-q');
    const a = item.querySelector('.faq-a');
    q?.addEventListener('click', () => {
      const open = item.classList.toggle('open');
      a.style.maxHeight = open ? a.scrollHeight + 'px' : '0px';
    });
  });
}

document.addEventListener('DOMContentLoaded', () => {
  setupMenu();
  setupLoadMore();
  setupDonationTabs();
  setupFaq();
});
EOF

